import type {HandoffScope} from './cashier-handoff';
export type SettlementSelection={scope:HandoffScope;match:string;deposit:string;statement:string;amount:string;period:string;date:string};
const uuid=(v:unknown):v is string=>typeof v==='string'&&/^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$/.test(v);
function obj(v:unknown):Record<string,unknown>{if(!v||typeof v!=='object'||Array.isArray(v))throw Error('Invalid settlement preview.');return v as Record<string,unknown>}
function date(v:unknown):v is string{return typeof v==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(v)&&!Number.isNaN(Date.parse(v))&&new Date(v).toISOString().slice(0,10)===v}
export function readBankSettlementPreview(value:unknown,s:SettlementSelection){
 const v=obj(value),c=obj(v.command);if(![...Object.values(s.scope),s.match,s.deposit,s.statement,s.period].every(uuid)||!date(s.date)||! /^[1-9][0-9]{0,11}$/.test(s.amount))throw Error('Invalid settlement selection.');
 if(v.schema_version!==1||v.tenant_id!==s.scope.tenant||v.property_id!==s.scope.property||v.actor_id!==s.scope.actor||v.match_id!==s.match||v.deposit_id!==s.deposit||v.statement_id!==s.statement||v.amount_minor!==s.amount||v.period_id!==s.period||v.posting_date!==s.date||!uuid(v.deposit_journal_id)||!uuid(v.mapping_id)||v.sources_reconciled!==true||!Array.isArray(v.blockers)||v.blockers.length||v.bank_verified!==false||v.journal_posted!==false)throw Error('Settlement preview does not match the selected credit.');
 if(!date(v.statement_value_date)||!date(v.deposit_posting_date)||s.date<v.statement_value_date||s.date<v.deposit_posting_date)throw Error('Settlement precedes its source dates.');
 if(c.currency!=='USD'||c.description!=='Matched deposit settlement to bank'||c.source_kind!=='cashier_bank_settlement'||c.source_id!==s.match||c.source_version!==1||c.period_id!==s.period||c.posting_date!==s.date||!Array.isArray(c.lines)||c.lines.length!==2||!Array.isArray(v.proposed_lines)||v.proposed_lines.length!==2)throw Error('Invalid settlement journal command.');
 const debit=obj(c.lines[0]),credit=obj(c.lines[1]);if(!uuid(debit.account_id)||!uuid(credit.account_id)||debit.account_id===credit.account_id||debit.side!=='debit'||credit.side!=='credit'||debit.amount_minor!==s.amount||credit.amount_minor!==s.amount)throw Error('Settlement journal does not balance.');
 for(let i=0;i<2;i++){const line=obj(c.lines[i]),proposed=obj(v.proposed_lines[i]);if(line.account_id!==proposed.account_id||line.side!==proposed.side||line.amount_minor!==proposed.amount_minor)throw Error('Settlement lines changed.');}
 return {raw:v,debitAccount:debit.account_id,creditAccount:credit.account_id};
}

export type BankSettlementRequest={id:string;selection:SettlementSelection;review:Record<string,unknown>};
function checked(r:BankSettlementRequest){if(!uuid(r.id))throw Error('Invalid settlement request.');readBankSettlementPreview(r.review,r.selection);return r}
export function readBankSettlementReceipt(value:unknown,r:BankSettlementRequest){checked(r);const v=obj(value),s=r.selection;if(v.schema_version!==1||v.tenant_id!==s.scope.tenant||v.property_id!==s.scope.property||v.actor_id!==s.scope.actor||v.request_id!==r.id||v.match_id!==s.match||v.amount_minor!==s.amount||!uuid(v.journal_id)||typeof v.replayed!=='boolean'||v.journal_posted!==true||v.verifies_settlement!==false)throw Error('Settlement receipt does not match the saved request.');return v}
function canonical(value:unknown):string{if(Array.isArray(value))return '['+value.map(canonical).join(',')+']';if(value&&typeof value==='object')return '{'+Object.entries(value).sort(([a],[b])=>a.localeCompare(b)).map(([k,v])=>JSON.stringify(k)+':'+canonical(v)).join(',')+'}';return JSON.stringify(value)}
export function readBankSettlementStatus(value:unknown,r:BankSettlementRequest){checked(r);const v=obj(value),s=r.selection.scope;if(v.schema_version!==1||v.tenant_id!==s.tenant||v.property_id!==s.property||v.actor_id!==s.actor||v.request_id!==r.id||typeof v.found!=='boolean'||typeof v.cancelled!=='boolean'||typeof v.journal_reversed!=='boolean'||(v.found&&v.cancelled))throw Error('Settlement recovery scope changed.');if(!v.found){if(v.result!==null||v.review!==null||v.journal_reversed)throw Error('Invalid settlement recovery.');return {state:v.cancelled?'cancelled' as const:'missing' as const,result:null,reversed:false}}if(canonical(v.review)!==canonical(r.review))throw Error('Recovered settlement has a different review.');return {state:'posted' as const,result:readBankSettlementReceipt(v.result,r),reversed:v.journal_reversed}}
type Store=Pick<Storage,'getItem'|'setItem'|'removeItem'>;
function storageKey(scope:HandoffScope,match:string){if(![...Object.values(scope),match].every(uuid))throw Error('Invalid settlement storage scope.');return 'irp.bank.settlement.v1:'+[scope.tenant,scope.property,scope.actor].join(':')+':'+match}
export function retainBankSettlement(store:Store,r:BankSettlementRequest){checked(r);const key=storageKey(r.selection.scope,r.selection.match),prior=store.getItem(key);if(prior!==null&&canonical(JSON.parse(prior))!==canonical(r))throw Error('Recover or cancel the previous settlement first.');store.setItem(key,JSON.stringify(r));if(store.getItem(key)!==JSON.stringify(r))throw Error('Unable to retain settlement request.');}
export function restoreBankSettlement(store:Store,scope:HandoffScope,match:string){const raw=store.getItem(storageKey(scope,match));if(raw===null)return null;const r=JSON.parse(raw) as BankSettlementRequest;checked(r);if(canonical(r.selection.scope)!==canonical(scope)||r.selection.match!==match)throw Error('Saved settlement belongs to another workspace.');return r}
export function clearBankSettlement(store:Store,r:BankSettlementRequest,status:unknown){const parsed=readBankSettlementStatus(status,r);if(parsed.state==='missing')throw Error('Check or cancel the settlement before clearing it.');const key=storageKey(r.selection.scope,r.selection.match),prior=restoreBankSettlement(store,r.selection.scope,r.selection.match);if(prior&&canonical(prior)!==canonical(r))throw Error('Saved settlement changed.');store.removeItem(key);return parsed}
